/**
 * SCRPT desktop shell.
 * Ensures the local engine (:8000) and frontend (:3000) are running, then
 * opens the studio in a native window. Servers are left running on quit —
 * the engine is a companion service, not a child of the window.
 */

const { app, BrowserWindow, ipcMain, powerSaveBlocker, shell } = require("electron");
const { spawn } = require("child_process");
const fs = require("fs");
const http = require("http");
const os = require("os");
const path = require("path");

// Install-specific paths (rewritten by the installer if the repo moves)
const BOOKR_DIR = "/Users/tiger/Desktop/CATALOG ENGINE/bookr";
const FRONTEND_DIR = path.join(os.homedir(), ".scrpt", "dev", "frontend");
const NPM = "/Users/tiger/.nvm/versions/node/v20.20.0/bin/npm";
const LOG_DIR = path.join(os.homedir(), ".scrpt");

const ENGINE_URL = "http://127.0.0.1:8000/api/health";
const FRONTEND_URL = "http://localhost:3000";
const START_URL = `${FRONTEND_URL}/front`;

function ping(url) {
  return new Promise((resolve) => {
    const req = http.get(url, { timeout: 2500 }, (res) => {
      res.resume();
      resolve(res.statusCode && res.statusCode < 500);
    });
    req.on("error", () => resolve(false));
    req.on("timeout", () => { req.destroy(); resolve(false); });
  });
}

function spawnDetached(cmd, args, cwd, logFile, env = {}) {
  fs.mkdirSync(LOG_DIR, { recursive: true });
  const out = fs.openSync(path.join(LOG_DIR, logFile), "a");
  const child = spawn(cmd, args, {
    cwd,
    detached: true,
    stdio: ["ignore", out, out],
    env: { ...process.env, ...env },
  });
  child.unref();
}

async function ensureServers(onStatus) {
  if (!(await ping(ENGINE_URL))) {
    onStatus("Starting the engine…");
    spawnDetached(
      "/usr/bin/python3",
      ["-m", "uvicorn", "engine.main:app", "--port", "8000", "--host", "127.0.0.1"],
      BOOKR_DIR, "engine.log", { PYTHONPATH: BOOKR_DIR },
    );
  }
  if (!(await ping(FRONTEND_URL))) {
    onStatus("Setting the type…");
    spawnDetached(NPM, ["run", "dev"], FRONTEND_DIR, "frontend.log");
  }
  // wait for both (up to 90s)
  for (let i = 0; i < 90; i++) {
    const [e, f] = await Promise.all([ping(ENGINE_URL), ping(FRONTEND_URL)]);
    if (e && f) return true;
    onStatus(e ? "Setting the type…" : "Starting the engine…");
    await new Promise((r) => setTimeout(r, 1000));
  }
  return false;
}

const SPLASH_HOLD_MS = 5000; // opening screen stays up at least this long

const SPLASH = `data:text/html;charset=utf-8,${encodeURIComponent(`
  <html><body style="margin:0;background:#0e0c09;display:flex;align-items:center;
  justify-content:center;height:100vh;flex-direction:column;">
  <img src="data:image/png;base64," style="width:380px;" />
  <div id="s" style="color:#83786a;font-size:13px;letter-spacing:0.34em;
  text-transform:uppercase;margin-top:-72px;font-family:system-ui,sans-serif;">Warming the presses…</div>
  </body></html>`)}`;

async function createWindow() {
  const win = new BrowserWindow({
    width: 1500,
    height: 950,
    minWidth: 1050,
    minHeight: 700,
    backgroundColor: "#0e0c09",
    title: "SCRPT",
    show: true,
    fullscreen: true, // STCKR-style: the studio takes the whole screen
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
    },
  });

  ipcMain.removeHandler("toggle-fullscreen");
  ipcMain.removeHandler("is-fullscreen");
  ipcMain.handle("toggle-fullscreen", () => {
    win.setFullScreen(!win.isFullScreen());
    return win.isFullScreen();
  });
  ipcMain.handle("is-fullscreen", () => win.isFullScreen());

  // Fullscreen = the studio wall display: keep the screen awake (no display
  // sleep, no screen saver) while SCRPT owns the screen. Windowed mode
  // releases the block so normal energy settings apply.
  let sleepBlockId = null;
  const holdScreenAwake = () => {
    const wantBlock = win.isFullScreen();
    if (wantBlock && sleepBlockId === null) {
      sleepBlockId = powerSaveBlocker.start("prevent-display-sleep");
    } else if (!wantBlock && sleepBlockId !== null) {
      powerSaveBlocker.stop(sleepBlockId);
      sleepBlockId = null;
    }
  };
  win.on("enter-full-screen", holdScreenAwake);
  win.on("leave-full-screen", holdScreenAwake);
  win.on("closed", () => {
    if (sleepBlockId !== null) {
      powerSaveBlocker.stop(sleepBlockId);
      sleepBlockId = null;
    }
  });
  holdScreenAwake(); // launches fullscreen — block from the first frame

  win.loadURL(SPLASH);

  // external links open in the real browser
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (!url.startsWith(FRONTEND_URL)) {
      shell.openExternal(url);
      return { action: "deny" };
    }
    return { action: "allow" };
  });

  const splashShownAt = Date.now();
  const ok = await ensureServers((msg) => {
    win.webContents.executeJavaScript(
      `document.getElementById('s') && (document.getElementById('s').textContent = ${JSON.stringify(msg)})`,
    ).catch(() => {});
  });

  const remaining = SPLASH_HOLD_MS - (Date.now() - splashShownAt);
  if (remaining > 0) await new Promise((r) => setTimeout(r, remaining));

  if (ok) {
    win.loadURL(START_URL);
  } else {
    win.loadURL(SPLASH.replace(
      encodeURIComponent("Opening SCRPT…"),
      encodeURIComponent("Could not start the local servers — see ~/.scrpt/*.log"),
    ));
  }
}

app.whenReady().then(createWindow);
app.on("window-all-closed", () => app.quit());
app.on("activate", () => {
  if (BrowserWindow.getAllWindows().length === 0) createWindow();
});
